const input = $input.first().json;
const executionId = `exec_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
return [{ json: { ...input, execution_id: executionId, status: 'accepted', estimated_duration_ms: 240000, workflow_version: 'v1' } }];

// ─────────────────────────────────────────────────────────────────────────
// MEDIA CONTACT DISCOVERY — connect a real data source here:
//   MEDIA_CONTACT_DISCOVERY_API_KEY (blog/radio/DJ/curator discovery + email
//   verification vendor of your choice).
// Email SENDING itself is already fully wired — the backend requires one of
// RESEND_API_KEY / SENDGRID_API_KEY / SMTP_HOST at startup (see
// backend/src/server.ts::validateEmailProvider and modules/outreach). This
// workflow's only gap is contact *discovery*, not delivery.
// ─────────────────────────────────────────────────────────────────────────
const input = $input.first().json;
const missing = [];
if (!$env.MEDIA_CONTACT_DISCOVERY_API_KEY) missing.push('MEDIA_CONTACT_DISCOVERY_API_KEY');

return [{ json: {
  mission_id: input.mission_id,
  execution_id: input.execution_id,
  status: missing.length ? 'partial' : 'completed',
  summary: missing.length ? `Outreach Intelligence ready — waiting on: ${missing.join(', ')}` : 'Press outreach campaign complete',
  results: {
    emails_sent: missing.length ? 0 : null,
    opens: missing.length ? 0 : null,
    clicks: missing.length ? 0 : null,
    replies: missing.length ? 0 : null,
    bounce_rate: missing.length ? null : null,
    missing_credentials: missing,
  },
} }];
